INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l34','be asked to do','',NULL,'/bi æskt tuː duː/','He was asked to call at the station.','他被要求到警局去一趟。','I was asked to make a speech.','我被邀请作演讲。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l34','pick up','',NULL,'/pɪk ʌp/','The bicycle was picked up in a village.','自行车在一个村子里被找到。','He picked up the phone.','他拿起了电话。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l34','call at','',NULL,'/kɔːl æt/','He was asked to call at the station.','他被要求到警局去一趟。','Please call at my office.','请到我办公室来一趟。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l34','most + 过去分词','',NULL,'/moʊst/','Dan was most surprised.','丹非常吃惊。','I was most pleased to hear it.','听到这事我非常高兴。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',5,'am2_l34_gp1','choice','{"stem":"\"This bridge ___ built in 1942.\"(被动,一般过去)","options":["is","has","did","was"],"answer_index":3,"stem_cn":"这座桥是1942年建的。","explanation_cn":"被动语态 be + 过去分词,单数主语一般过去用 was。✓ This bridge was built in 1942 桥是1942年建的。✗ is:讲的是过去;✗ did:助动词不构成被动;✗ has:那是完成时。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',5,'am2_l34_gp1','choice','{"stem":"\"The letter ___ written by Dan''s friend.\"(被动,一般过去)","options":["has","was","did","is"],"answer_index":1,"stem_cn":"这封信是丹的朋友写的。","explanation_cn":"被动语态,单数主语一般过去用 was + 过去分词。✓ The letter was written by his friend 信是朋友写的。✗ is:讲的是过去;✗ did:不构成被动;✗ has:完成时。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',5,'am2_l34_gp2','choice','{"stem":"\"Dan''s bicycle ___ stolen twenty years ago.\"(一般过去被动)","options":["was","did","is","has"],"answer_index":0,"stem_cn":"丹的自行车是20年前被偷的。","explanation_cn":"\"被偷\"是被动,一般过去用 was + stolen。✓ It was stolen twenty years ago 20年前被偷的。✗ is:讲过去;✗ has:完成时;✗ did:不构成被动。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',5,'am2_l34_gp2','choice','{"stem":"\"The bicycle ___ picked up in a small village.\"(一般过去被动)","options":["is","did","has","was"],"answer_index":3,"stem_cn":"自行车在一个小村子里被找到。","explanation_cn":"\"被找到\"是被动,一般过去用 was + picked up。✓ The bicycle was picked up 自行车被找到。✗ is:讲过去;✗ has:完成时;✗ did:不构成被动。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',5,'am2_l34_gp2','choice','{"stem":"\"The prisoners ___ set free after the war.\"(复数主语,一般过去被动)","options":["was","are","were","did"],"answer_index":2,"stem_cn":"战后囚犯们被释放了。","explanation_cn":"主语是复数(prisoners),一般过去被动用 were。✓ The prisoners were set free 囚犯被释放。✗ was:主语是复数;✗ are:讲的是过去;✗ did:不构成被动。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',5,'am2_l34_gp3','choice','{"stem":"\"The bicycle ___ now being sent to his home.\"(现在进行被动)","options":["was","is","has","had"],"answer_index":1,"stem_cn":"自行车现在正被送回他家。","explanation_cn":"现在进行被动 is + being + 过去分词,单数主语用 is。✓ It is now being sent 现在正被送。✗ was:那是过去;✗ has / had:那是完成时。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',5,'am2_l34_gp3','choice','{"stem":"\"The bridge is ___ repaired at the moment.\"(此刻正被…,进行时被动)","options":["being","be","been","to be"],"answer_index":0,"stem_cn":"这座桥此刻正在被修。","explanation_cn":"现在进行时的被动:be + being + 过去分词,中间用 being。✓ is being repaired 正在被修。✗ been:那是完成时;✗ be / to be:不构成进行时被动。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',5,'am2_l34_gp3','choice','{"stem":"\"The rooms are ___ cleaned right now.\"(此刻正被…,进行时被动)","options":["be","been","to be","being"],"answer_index":3,"stem_cn":"房间现在正被打扫。","explanation_cn":"现在进行被动中间用 being。✓ are being cleaned 正在被打扫。✗ been:完成时;✗ be / to be:不合。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',5,'am2_l34_gp4','choice','{"stem":"\"He was told his bicycle ___ been found.\"(过去完成被动)","options":["was","did","had","has"],"answer_index":2,"stem_cn":"他被告知自行车已被找到。","explanation_cn":"过去完成被动 had + been + 过去分词。✓ his bicycle had been found 自行车已被找到。✗ was:少了完成含义;✗ has:讲的是过去(told 之前);✗ did:不构成被动。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',5,'am2_l34_gp4','choice','{"stem":"\"When he arrived, the work ___ already been finished.\"(过去完成被动)","options":["had","was","has","did"],"answer_index":0,"stem_cn":"他到时,工作已经被完成了。","explanation_cn":"过去完成被动 had + been + 过去分词。✓ the work had already been finished 工作已被完成。✗ was:缺完成含义;✗ has:讲的是过去;✗ did:不构成被动。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',5,'am2_l34_gp5','choice','{"stem":"\"In the letter, Dan ___ asked to call at the station.\"(被动:被要求)","options":["has","did","was","is"],"answer_index":2,"stem_cn":"信里丹被要求到警局去一趟。","explanation_cn":"\"被要求\"是被动,一般过去用 was + asked。✓ Dan was asked to call 丹被要求去一趟。✗ did:不构成被动;✗ has:完成时;✗ is:讲的是过去。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',5,'am2_l34_gp5','choice','{"stem":"\"I was asked ___ make a speech at the party.\"(被动 be asked 后接动词不定式)","options":["of","to","at","for"],"answer_index":1,"stem_cn":"聚会上我被邀请作演讲。","explanation_cn":"be asked 之后接动词不定式,用 to。✓ I was asked to make a speech 我被邀请作演讲。✗ for / at / of:不接不定式。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',5,'am2_l34_gp6','choice','{"stem":"\"This bridge was built ___ prisoners of war.\"(引出动作的执行者)","options":["by","for","from","with"],"answer_index":0,"stem_cn":"这座桥是战俘建造的。","explanation_cn":"被动句里引出动作执行者用 by。✓ built by prisoners of war 由战俘建造。✗ with:表工具;✗ from:表来源;✗ for:表目的。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',5,'am2_l34_gp6','choice','{"stem":"\"He was told the news ___ a smiling policeman.\"(引出动作的执行者)","options":["to","with","from","by"],"answer_index":3,"stem_cn":"一位面带微笑的警察告诉了他这个消息。","explanation_cn":"引出动作执行者(告诉他的人)用 by。✓ told by a smiling policeman 由一位微笑的警察告知。✗ with:工具;✗ from:来源;✗ to:方向。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',5,'am2_l34_gp7','choice','{"stem":"\"Dan was ___ surprised when he heard the news.\"(表''非常'',与过去分词连用)","options":["mostly","almost","most","the most"],"answer_index":2,"stem_cn":"听到消息时丹非常吃惊。","explanation_cn":"most = very,表\"非常\",与作形容词的过去分词连用。✓ Dan was most surprised 丹非常吃惊。✗ almost:意为\"几乎\";✗ mostly:意为\"大多\";✗ the most:那是最高级。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',5,'am2_l34_gp7','choice','{"stem":"\"I was ___ pleased to hear the good news.\"(表''非常'',与过去分词连用)","options":["almost","the most","mostly","most"],"answer_index":3,"stem_cn":"听到好消息我非常高兴。","explanation_cn":"most = very,表\"非常\"。✓ I was most pleased 我非常高兴。✗ almost:几乎;✗ mostly:大多;✗ the most:最高级。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',5,'am2_l34_gp8','choice','{"stem":"\"Dan was surprised, and he was amused ___.\"(句尾表''也'')","options":["yet","either","too","also too"],"answer_index":2,"stem_cn":"丹很吃惊,也觉得好笑。","explanation_cn":"句尾表\"也\"用 too。✓ He was amused too 他也觉得好笑。✗ also too:重复;✗ either:用于否定句;✗ yet:意为\"还、尚\"。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',5,'am2_l34_gp8','choice','{"stem":"\"He never expected it, but he was pleased ___ well.\"(与 well 搭配表''也'')","options":["as","too","so","very"],"answer_index":0,"stem_cn":"他没料到,但也很高兴。","explanation_cn":"as well 表\"也\",与 well 搭配。✓ he was pleased as well 他也很高兴。✗ so / too / very:不与 well 构成\"也\"的短语。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',6,NULL,'choice','{"stem":"美语里\"警察\"中性说法常用:","options":["policeman","cop man","police guy","police officer"],"answer_index":3,"explanation_cn":"美语里\"警察\"中性说法常用 police officer(口语 cop);英式说 policeman。✓ a police officer 一名警察。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',6,NULL,'choice','{"stem":"美语里\"邮件\"常说:","options":["post","mail","letter box","send paper"],"answer_index":1,"explanation_cn":"美语里\"邮件\"常说 mail;英式说 post。✓ He got the mail 他收到了邮件。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',6,NULL,'choice','{"stem":"receive 的意思是:","options":["收到","撕毁","寄出","阅读"],"answer_index":0,"explanation_cn":"receive = 收到。✓ received a letter 收到一封信。\n顺带记:寄出 = send;当地的 = local;消息 = news."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',6,NULL,'choice','{"stem":"wonder 的意思是:","options":["忘记","想知道,纳闷","抱怨","确信"],"answer_index":1,"explanation_cn":"wonder = 想知道、纳闷。✓ Dan wondered why 丹纳闷为什么。\n顺带记:指望 = expect;逗乐 = amuse;偷 = steal."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',6,NULL,'choice','{"stem":"amuse 的意思是:","options":["安慰","吓唬","逗乐,使觉得好笑","激怒"],"answer_index":2,"explanation_cn":"amuse = 逗乐、使觉得好笑。✓ He was amused 他觉得好笑。\n顺带记:想知道 = wonder;收到 = receive;村庄 = village."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',6,NULL,'choice','{"stem":"expect 的意思是:","options":["拒绝","放弃","怀疑","指望,预料"],"answer_index":3,"explanation_cn":"expect = 指望、预料。✓ never expected it to be found 从没指望能找到。\n顺带记:收到 = receive;想知道 = wonder;偷 = steal."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',7,NULL,'cloze','{"stem":"第 1 空","context":"Dan was asked ___1___ call at the station. There he was told that his bicycle ___2___ been found. It ___3___ now being sent to his home. The bicycle ___4___ stolen twenty years ago.","blank_no":1,"options":["to","for","at","of"],"answer_index":0,"explanation_cn":"be asked 之后接动词不定式,用 to。✓ was asked to call at the station 被要求去警局。\n✗ for / at / of:不接不定式。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',7,NULL,'cloze','{"stem":"第 2 空","context":"Dan was asked ___1___ call at the station. There he was told that his bicycle ___2___ been found. It ___3___ now being sent to his home. The bicycle ___4___ stolen twenty years ago.","blank_no":2,"options":["had","was","has","is"],"answer_index":0,"explanation_cn":"过去完成被动 had + been + 过去分词。✓ his bicycle had been found 自行车已被找到。\n✗ was:缺完成含义;✗ has:讲的是过去;✗ is:讲的是过去。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',7,NULL,'cloze','{"stem":"第 3 空","context":"Dan was asked ___1___ call at the station. There he was told that his bicycle ___2___ been found. It ___3___ now being sent to his home. The bicycle ___4___ stolen twenty years ago.","blank_no":3,"options":["is","was","has","had"],"answer_index":0,"explanation_cn":"现在进行被动 is + being + 过去分词。✓ It is now being sent 现在正被送。\n✗ was:那是过去;✗ has / had:完成时。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',7,NULL,'cloze','{"stem":"第 4 空","context":"Dan was asked ___1___ call at the station. There he was told that his bicycle ___2___ been found. It ___3___ now being sent to his home. The bicycle ___4___ stolen twenty years ago.","blank_no":4,"options":["was","is","has","had"],"answer_index":0,"explanation_cn":"一般过去被动 was + 过去分词。✓ It was stolen twenty years ago 20年前被偷。\n✗ is:讲过去;✗ has / had:完成时。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',8,NULL,'choice','{"stem":"Why did Dan receive a letter from the police?","options":["He was asked to join the police","He had won a prize","His lost bicycle had been found","He had broken the law"],"answer_index":2,"explanation_cn":"课文说 he was told… his bicycle had been found,警察通知他丢失的自行车找到了。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',8,NULL,'choice','{"stem":"Where was the bicycle picked up?","options":["In a small village four hundred miles away","At a big city market","At the local station","In Dan''s own garden"],"answer_index":0,"explanation_cn":"课文说 the bicycle was picked up in a small village four hundred miles away。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',8,NULL,'choice','{"stem":"When was the bicycle stolen?","options":["When Dan was a grown man","Last Tuesday","Five days ago","Twenty years ago, when Dan was fifteen"],"answer_index":3,"explanation_cn":"课文结尾 It was stolen twenty years ago when Dan was a boy of fifteen。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',9,NULL,'choice','{"stem":"你想说\"这座桥是1942年建的\"(被动:be + 过去分词):","options":["This bridge was built in 1942.","This bridge was build in 1942.","This bridge built in 1942.","This bridge is build in 1942."],"answer_index":0,"explanation_cn":"被动语态用 be + 过去分词。✓ This bridge was built in 1942. 场合:说某物\"被…\"而不强调是谁做的。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',9,NULL,'choice','{"stem":"你想说\"自行车正用火车运回来\"(现在进行被动:is being + 过去分词):","options":["The bicycle is sent being by train.","The bicycle being sent by train.","The bicycle is sending by train.","The bicycle is being sent by train."],"answer_index":3,"explanation_cn":"现在进行被动用 is + being + 过去分词。✓ The bicycle is being sent by train. 场合:说某事此刻正被…。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',9,NULL,'choice','{"stem":"你想说\"我被邀请作一次演讲\"(被动:was asked to do):","options":["I am asked making a speech.","I was asked to make a speech.","I asked to make a speech.","I was ask to make a speech."],"answer_index":1,"explanation_cn":"被动 be asked,后面仍接动词不定式。✓ I was asked to make a speech. 场合:说自己被要求/被邀请做某事。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',10,NULL,'choice','{"stem":"receive 的意思是:","options":["寄出","收到","购买","丢失"],"answer_index":1,"explanation_cn":"receive = 收到。✓ received a letter 收到一封信。\n顺带记:寄出 = send;丢失 = lose;购买 = buy."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',10,NULL,'choice','{"stem":"amuse 的意思是:","options":["吓唬","激怒","无聊","逗乐,使觉得好笑"],"answer_index":3,"explanation_cn":"amuse = 逗乐、使觉得好笑。✓ He was amused 他觉得好笑。\n顺带记:激怒 = annoy;想知道 = wonder;指望 = expect."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',10,NULL,'choice','{"stem":"\"This bridge ___ built in 1942.\"(被动:be + 过去分词)","options":["has","was","is","did"],"answer_index":1,"stem_cn":"这座桥是1942年建的。","explanation_cn":"被动语态一般过去用 was + 过去分词。✓ This bridge was built in 1942 桥是1942年建的。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',10,NULL,'choice','{"stem":"\"The bicycle ___ now being sent home.\"(现在进行被动)","options":["was","had","has","is"],"answer_index":3,"stem_cn":"自行车正被运回家。","explanation_cn":"现在进行被动用 is + being + 过去分词。✓ The bicycle is now being sent home 自行车正被运回家。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',10,NULL,'choice','{"stem":"\"His bicycle had been found.\" 这句话的意思是:","options":["他卖掉了自行车。","他把自行车弄丢了。","他的自行车已经被找到了。","他要去找自行车。"],"answer_index":2,"explanation_cn":"His bicycle had been found. 过去完成被动,意思是\"他的自行车已经被找到了\"。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',10,NULL,'choice','{"stem":"\"It was stolen twenty years ago.\" 这句话的意思是:","options":["它20年前坏了。","它是20年前被偷的。","它20年前就卖了。","它20年前找到了。"],"answer_index":1,"explanation_cn":"It was stolen twenty years ago. 一般过去被动,意思是\"它是20年前被偷的\"。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',10,NULL,'choice','{"stem":"Why is Dan not worried anymore?","options":["He gave up his old bicycle","The police let him go free","He bought a new bicycle","He learned his lost bicycle had been found"],"answer_index":3,"passage":"Dan Robinson has been worried all week. Last Tuesday he received a letter from the local police. In the letter, he was asked to call at the station. Dan wondered why he was wanted by the police, but he went to the station yesterday and now he is not worried anymore. At the station, he was told by a smiling policeman that his bicycle had been found. Five days ago, the policeman told him, the bicycle was picked up in a small village four hundred miles away. It is now being sent to his home by train. Dan was most surprised when he heard the news. He was amused too, because he never expected the bicycle to be found. It was stolen twenty years ago when Dan was a boy of fifteen!","explanation_cn":"课文说他到警局得知自行车已被找到,所以 now he is not worried anymore 不再担心了。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',10,NULL,'choice','{"stem":"Why was Dan amused?","options":["The policeman told a funny joke","He never expected the bicycle to be found after twenty years","He got a big reward","The bicycle was broken"],"answer_index":1,"passage":"Dan Robinson has been worried all week. Last Tuesday he received a letter from the local police. In the letter, he was asked to call at the station. Dan wondered why he was wanted by the police, but he went to the station yesterday and now he is not worried anymore. At the station, he was told by a smiling policeman that his bicycle had been found. Five days ago, the policeman told him, the bicycle was picked up in a small village four hundred miles away. It is now being sent to his home by train. Dan was most surprised when he heard the news. He was amused too, because he never expected the bicycle to be found. It was stolen twenty years ago when Dan was a boy of fifteen!","explanation_cn":"课文说 he never expected the bicycle to be found,20年后失而复得,他觉得又惊又好笑。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',10,NULL,'choice','{"stem":"How long had it taken to find Dan''s bicycle?","options":["Five days","Four hundred days","Twenty years — it was stolen when he was fifteen","One week"],"answer_index":2,"audio":"Dan Robinson has been worried all week. Last Tuesday he received a letter from the local police. In the letter, he was asked to call at the station. Dan wondered why he was wanted by the police, but he went to the station yesterday and now he is not worried anymore. At the station, he was told by a smiling policeman that his bicycle had been found. Five days ago, the policeman told him, the bicycle was picked up in a small village four hundred miles away. It is now being sent to his home by train. Dan was most surprised when he heard the news. He was amused too, because he never expected the bicycle to be found. It was stolen twenty years ago when Dan was a boy of fifteen!","explanation_cn":"课文说车是20年前丹15岁时被偷的,如今才找到,所以\"神速\"是反语。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l34',10,NULL,'choice','{"stem":"How is the bicycle being sent to Dan?","options":["By ship","By train","By airplane","By mail truck"],"answer_index":1,"audio":"Dan Robinson has been worried all week. Last Tuesday he received a letter from the local police. In the letter, he was asked to call at the station. Dan wondered why he was wanted by the police, but he went to the station yesterday and now he is not worried anymore. At the station, he was told by a smiling policeman that his bicycle had been found. Five days ago, the policeman told him, the bicycle was picked up in a small village four hundred miles away. It is now being sent to his home by train. Dan was most surprised when he heard the news. He was amused too, because he never expected the bicycle to be found. It was stolen twenty years ago when Dan was a boy of fifteen!","explanation_cn":"课文说 It is now being sent to his home by train,自行车正用火车运回。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
